wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

/// The key under which the subscription list is stored, one URL per line.
const SUBSCRIPTIONS_KEY: &str = "urls";

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // An absent key means no subscriptions. An empty list is still a
        // present `urls` field, so the ensures clause holds in that case too.
        let urls: Vec<String> = match state_read::get(SUBSCRIPTIONS_KEY) {
            Some(text) => text
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
